void word(Bytes& b,std::uint32_t v){for(unsigned n=0;n<4;++n)b.push_back(std::uint8_t(v>>(n*8)));}
void text(Bytes& b,const std::string& s){word(b,std::uint32_t(s.size()));b.insert(b.end(),s.begin(),s.end());}
